 for p in select value from jsonb_array_elements('[{"id":"10000000-0000-4000-8000-000000000007","slug":"cursed-blood-manipulation-shirt","name":"Cursed Blood Manipulation Shirt","category":"Tops","price":3500,"badge":"NEW ARRIVAL","active":true,"description":"An oversized statement shirt built around the Cursed Blood Manipulation graphic. Cut with a relaxed silhouette and finished with bold red detailing across the back, creating a sharp contrast against the deep black fabric. Designed for an effortless streetwear fit with a strong visual identity.","images":["/products/cursed-blood-manipulation/01-cover.jpeg","/products/cursed-blood-manipulation/02-back.jpeg","/products/cursed-blood-manipulation/03-side.jpeg","/products/cursed-blood-manipulation/04-detail.jpeg","/products/cursed-blood-manipulation/05-outfit.jpeg"],"product_variants":[{"id":"20000000-0000-4000-8000-000000000700","product_id":"10000000-0000-4000-8000-000000000007","size":"S","color":"Black","color_hex":"#222222","stock":12},{"id":"20000000-0000-4000-8000-000000000701","product_id":"10000000-0000-4000-8000-000000000007","size":"M-L","color":"Black","color_hex":"#222222","stock":12},{"id":"20000000-0000-4000-8000-000000000702","product_id":"10000000-0000-4000-8000-000000000007","size":"XL","color":"Black","color_hex":"#222222","stock":12}],"original_price":null,"size_guide":null},{"id":"10000000-0000-4000-8000-000000000008","slug":"sakura-long-sleeve","name":"Sakura Long Sleeve","category":"Tops","price":3800,"badge":"NEW ARRIVAL","active":true,"description":"Sakura Long Sleeve — a relaxed statement piece inspired by Japanese aesthetics, featuring a detailed cherry blossom graphic across the back with contrasting black calligraphy. The clean white base and oversized silhouette keep the front minimal while allowing the artwork to define the piece. Designed for an effortless streetwear fit and easy everyday layering.","images":["/products/sakura-long-sleeve/01-cover.jpeg","/products/sakura-long-sleeve/02-rear.jpeg","/products/sakura-long-sleeve/03-detail.jpeg","/products/sakura-long-sleeve/04-models.jpeg","/products/sakura-long-sleeve/05-angled.jpeg"],"product_variants":[{"id":"20000000-0000-4000-8000-000000000800","product_id":"10000000-0000-4000-8000-000000000008","size":"S","color":"White","color_hex":"#eeede5","stock":12},{"id":"20000000-0000-4000-8000-000000000801","product_id":"10000000-0000-4000-8000-000000000008","size":"M-L","color":"White","color_hex":"#eeede5","stock":12},{"id":"20000000-0000-4000-8000-000000000802","product_id":"10000000-0000-4000-8000-000000000008","size":"XL","color":"White","color_hex":"#eeede5","stock":12}],"original_price":null,"size_guide":{"image":"/products/sakura-long-sleeve/size-chart.jpeg","alt":"Sakura size chart: S, M-L, XL. A: 60, 62, 65. B: 60, 63, 65. C: 73, 74, 76."}},{"id":"10000000-0000-4000-8000-000000000009","slug":"sakura-shirt","name":"Sakura Shirt","category":"Tops","price":3700,"badge":"NEW ARRIVAL","active":true,"description":"Sakura Shirt — a relaxed oversized statement piece featuring a Japanese-inspired cherry blossom graphic flowing across the upper back and shoulder. The clean white base keeps the silhouette minimal while the black and soft pink Sakura artwork creates the focal point. Designed with a loose, effortless fit for everyday streetwear styling.","images":["/products/sakura-shirt/01-cover.jpeg","/products/sakura-shirt/02-rear.jpeg","/products/sakura-shirt/03-side.jpeg","/products/sakura-shirt/04-front.jpeg"],"product_variants":[{"id":"20000000-0000-4000-8000-000000000900","product_id":"10000000-0000-4000-8000-000000000009","size":"S","color":"White","color_hex":"#eeede5","stock":12},{"id":"20000000-0000-4000-8000-000000000901","product_id":"10000000-0000-4000-8000-000000000009","size":"M-L","color":"White","color_hex":"#eeede5","stock":12},{"id":"20000000-0000-4000-8000-000000000902","product_id":"10000000-0000-4000-8000-000000000009","size":"XL","color":"White","color_hex":"#eeede5","stock":12}],"original_price":null,"size_guide":{"image":"/products/sakura-long-sleeve/size-chart.jpeg","alt":"Sakura size chart: S, M-L, XL. A: 60, 62, 65. B: 60, 63, 65. C: 73, 74, 76."}},{"id":"10000000-0000-4000-8000-000000000010","slug":"slim-fit-shirt-blue-navy","name":"Slim Fit Shirt Blue Navy","category":"Tops","price":2000,"badge":"NEW ARRIVAL","active":true,"description":"A clean everyday essential designed with a close, streamlined silhouette. Finished in a deep navy tone, this shirt delivers a minimal and versatile look with a sharp fitted shape. Its simple construction makes it easy to style on its own or combine with other pieces for a clean everyday outfit.","images":["/products/slim-fit-shirt-blue-navy/01-cover.jpeg","/products/slim-fit-shirt-blue-navy/02-front.jpeg","/products/slim-fit-shirt-blue-navy/03-back.jpeg"],"product_variants":[{"id":"20000000-0000-4000-8000-000000001000","product_id":"10000000-0000-4000-8000-000000000010","size":"S","color":"Navy","color_hex":"#151c29","stock":12},{"id":"20000000-0000-4000-8000-000000001001","product_id":"10000000-0000-4000-8000-000000000010","size":"M","color":"Navy","color_hex":"#151c29","stock":12},{"id":"20000000-0000-4000-8000-000000001002","product_id":"10000000-0000-4000-8000-000000000010","size":"L","color":"Navy","color_hex":"#151c29","stock":12},{"id":"20000000-0000-4000-8000-000000001003","product_id":"10000000-0000-4000-8000-000000000010","size":"XL","color":"Navy","color_hex":"#151c29","stock":12}],"original_price":null,"size_guide":null},{"id":"10000000-0000-4000-8000-000000000011","slug":"sakura-jeans","name":"Sakura Jeans","category":"Bottoms","price":6000,"badge":"NEW ARRIVAL","active":true,"description":"Sakura Jeans — a wide-leg black denim piece finished with a subtle Sakura-inspired graphic detail near the upper back pocket. The relaxed silhouette gives the jeans a loose streetwear shape, while the minimal floral accent connects the piece to the Sakura collection without overpowering the design. Built for an easy, oversized fit and everyday styling.","images":["/products/sakura-jeans/01-cover.jpeg","/products/sakura-jeans/02-detail.jpeg","/products/sakura-jeans/03-outdoor.jpeg"],"product_variants":[{"id":"20000000-0000-4000-8000-000000001100","product_id":"10000000-0000-4000-8000-000000000011","size":"S","color":"Black","color_hex":"#222222","stock":12},{"id":"20000000-0000-4000-8000-000000001101","product_id":"10000000-0000-4000-8000-000000000011","size":"M-L","color":"Black","color_hex":"#222222","stock":12},{"id":"20000000-0000-4000-8000-000000001102","product_id":"10000000-0000-4000-8000-000000000011","size":"XL","color":"Black","color_hex":"#222222","stock":12}],"original_price":null,"size_guide":{"image":"/products/sakura-jeans/size-chart.jpeg","alt":"Sakura Jeans size chart. S: length 110, waist 40, thighs 34. M-L: length 113, waist 42, thighs 36."}},{"id":"10000000-0000-4000-8000-000000000012","slug":"serpent-hunter-bootcut","name":"Serpent Hunter Bootcut","category":"Bottoms","price":5900,"badge":null,"active":true,"description":"Serpent Hunter Bootcut. Bootcut jeans with a flared leg, paired with the Slim Fit Shirt Blue Navy in the Bootcut + Slim Shirt Combo.","images":["/products/bootcut-jeans/01-cover.jpeg"],"size_guide":{"image":"/products/bootcut-jeans/size-chart.jpeg","alt":"Serpent Hunter Bootcut size chart. S: length 103, leg opening 17, thigh 28, rise 30. M: 106, 26, 29, 32. L: 108, 28, 30, 32. XL: 110, 31, 32, 33. Measurements in cm."},"product_variants":[{"id":"20000000-0000-4000-8000-000000001200","product_id":"10000000-0000-4000-8000-000000000012","size":"S","color":"Charcoal","color_hex":"#363638","stock":12},{"id":"20000000-0000-4000-8000-000000001201","product_id":"10000000-0000-4000-8000-000000000012","size":"M","color":"Charcoal","color_hex":"#363638","stock":12},{"id":"20000000-0000-4000-8000-000000001202","product_id":"10000000-0000-4000-8000-000000000012","size":"L","color":"Charcoal","color_hex":"#363638","stock":12},{"id":"20000000-0000-4000-8000-000000001203","product_id":"10000000-0000-4000-8000-000000000012","size":"XL","color":"Charcoal","color_hex":"#363638","stock":12}],"original_price":null}]'::jsonb) loop
  select slug into existing_slug from public.products where id=(p->>'id')::uuid;
  if found and existing_slug<>p->>'slug' then raise exception 'Original product ID is already used by another slug: %',p->>'slug'; end if;
  if exists(select 1 from public.outfits where slug=p->>'slug') then raise exception 'Product slug is already used by an outfit: %',p->>'slug'; end if;
  select id into actual_id from public.products where slug=p->>'slug';
  if not found then
   actual_id:=(p->>'id')::uuid;
   insert into public.products(id,slug,name,category,price,original_price,description,images,badge,active,size_guide)
   values(actual_id,p->>'slug',p->>'name',p->>'category',(p->>'price')::integer,(p->>'original_price')::integer,p->>'description',array(select jsonb_array_elements_text(p->'images')),p->>'badge',(p->>'active')::boolean,nullif(p->'size_guide','null'::jsonb));
  end if;
  product_id_map := product_id_map || jsonb_build_object(p->>'id',actual_id);
  for v in select value from jsonb_array_elements(p->'product_variants') loop
   if exists(select 1 from public.product_variants where id=(v->>'id')::uuid and product_id<>actual_id) then raise exception 'Original variant ID is already used by another product: %',v->>'id'; end if;
   -- Retain admin edits, sold stock and existing variant IDs; add only missing options.
   if not exists(select 1 from public.product_variants where id=(v->>'id')::uuid or (product_id=actual_id and lower(size)=lower(v->>'size') and lower(color)=lower(v->>'color'))) then
    insert into public.product_variants(id,product_id,size,color,color_hex,stock) values((v->>'id')::uuid,actual_id,v->>'size',v->>'color',v->>'color_hex',(v->>'stock')::integer);
   end if;
  end loop;
 end loop;
 for o in select value from jsonb_array_elements('[{"id":"40000000-0000-4000-8000-000000000001","slug":"bootcut-slim-shirt-combo","name":"BOOTCUT + SLIM SHIRT COMBO","price":6900,"original_price":7900,"image":"/outfits/bootcut-slim-combo/01-cover.jpeg","description":"Serpent Hunter Bootcut paired with Slim Fit Shirt Blue Navy. Choose a size for each piece.","active":true,"components":[{"product_id":"10000000-0000-4000-8000-000000000012"},{"product_id":"10000000-0000-4000-8000-000000000010","thumbnail":"/outfits/bootcut-slim-combo/shirt-thumbnail.jpeg"}],"images":["/outfits/bootcut-slim-combo/01-cover.jpeg"],"badge":null},{"id":"40000000-0000-4000-8000-000000000002","slug":"sakura-outfit-summer","name":"SAKURA OUTFIT SUMMER","price":8700,"original_price":9700,"image":"/outfits/sakura-summer/01-cover.jpeg","description":"Sakura Shirt paired with Sakura Jeans. Choose a size for each piece.","active":true,"components":[{"product_id":"10000000-0000-4000-8000-000000000009","thumbnail":"/outfits/sakura-summer/shirt-thumbnail.jpeg","size_guide":{"image":"/outfits/sakura-summer/shirt-size-chart.jpeg","alt":"Sakura Shirt size chart: S/M, L, XL. A: 60, 62, 65. B: 60, 63, 65. C: 73, 74, 76."}},{"product_id":"10000000-0000-4000-8000-000000000011","thumbnail":"/outfits/sakura-summer/jeans-thumbnail.jpeg"}],"images":["/outfits/sakura-summer/01-cover.jpeg"],"badge":null}]'::jsonb) loop
  select slug into existing_slug from public.outfits where id=(o->>'id')::uuid;
  if found and existing_slug<>o->>'slug' then raise exception 'Original outfit ID is already used by another slug: %',o->>'slug'; end if;
  if exists(select 1 from public.products where slug=o->>'slug') then raise exception 'Outfit slug is already used by a product: %',o->>'slug'; end if;
  if not exists(select 1 from public.outfits where slug=o->>'slug') then
   -- Reuse products already created with the same slug, even with different UUIDs.
   select jsonb_agg(c.value || jsonb_build_object('product_id',product_id_map->>(c.value->>'product_id')) order by c.ordinality) into components
   from jsonb_array_elements(o->'components') with ordinality c(value,ordinality);
   insert into public.outfits(id,slug,name,price,original_price,image,images,description,active,badge,components)
   values((o->>'id')::uuid,o->>'slug',o->>'name',(o->>'price')::integer,(o->>'original_price')::integer,o->'images'->>0,array(select jsonb_array_elements_text(o->'images')),o->>'description',(o->>'active')::boolean,o->>'badge',components);
  end if;
 end loop;
end;
$restore$;
commit;
-- Inspect the database-backed catalog, including products created by the owner.
select p.slug,p.name,p.category,p.price,p.active,count(v.id) as variants,coalesce(sum(v.stock),0) as stock
from public.products p left join public.product_variants v on v.product_id=p.id
group by p.id order by p.category,p.name;
select slug,name,price,original_price,active,components from public.outfits order by name;
